using System.ComponentModel.DataAnnotations;using System.Text.Json;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.AspNetCore.Mvc.Rendering;using Microsoft.EntityFrameworkCore;using NoryMusicLMS_VS.Data;using NoryMusicLMS_VS.Models;using NoryMusicLMS_VS.Services;
namespace NoryMusicLMS_VS.Areas.Admin.Pages.QuizQuestions;
[Authorize(Roles="Admin")] public class CreateModel:PageModel{private readonly ApplicationDbContext _db;
    private readonly AudioStorageService _audio;private readonly ImageStorageService _images;public CreateModel(ApplicationDbContext db,ImageStorageService images,AudioStorageService audio){_db=db;_images=images;_audio=audio;}[BindProperty]public InputModel Input{get;set;}=new();public class InputModel{[Required]public int QuizId{get;set;}[Required,StringLength(500)]public string QuestionText{get;set;}="";public QuestionType Type{get;set;}public int Points{get;set;}=1;public int OrderIndex{get;set;}=1;public string? Option1{get;set;}public string? Option2{get;set;}public string? Option3{get;set;}public string? Option4{get;set;}public int CorrectOptionNumber{get;set;}=1;public string? CorrectAnswerText{get;set;}public string? AudioUrl{get;set;}public string? ToneSequence{get;set;}public IFormFile? Image{get;set;}public IFormFile? Audio{get;set;}}
public async Task<IActionResult> OnGetAsync(){await LoadQuizzesAsync();return Page();}public async Task<IActionResult> OnPostAsync(){var quiz=await _db.Quizzes.Include(q=>q.Lesson).ThenInclude(l=>l.Course).FirstOrDefaultAsync(q=>q.Id==Input.QuizId&&q.Lesson.Course.IsActive);if(quiz is null)ModelState.AddModelError("Input.QuizId","Select a quiz from an active course.");if(Input.Points<1)ModelState.AddModelError("Input.Points","Points must be at least 1.");if(Input.Type is QuestionType.MultipleChoice or QuestionType.TrueFalse){var opts=BuildOptions();if(Input.Type==QuestionType.TrueFalse)opts=["True","False"];if(opts.Count<2)ModelState.AddModelError(string.Empty,"Provide at least two options.");if(Input.CorrectOptionNumber<1||Input.CorrectOptionNumber>opts.Count)ModelState.AddModelError("Input.CorrectOptionNumber","Choose a valid correct option.");}else if(string.IsNullOrWhiteSpace(Input.CorrectAnswerText))ModelState.AddModelError("Input.CorrectAnswerText","Enter the expected answer.");if(Input.Type==QuestionType.AudioIdentification&&string.IsNullOrWhiteSpace(Input.AudioUrl)&&Input.Audio is not { Length: > 0 }&&string.IsNullOrWhiteSpace(Input.ToneSequence))ModelState.AddModelError(string.Empty,"Add an audio URL or tone sequence.");if(ImageStorageService.Validate(Input.Image) is{ }e)ModelState.AddModelError("Input.Image",e);if(!ModelState.IsValid){await LoadQuizzesAsync();return Page();}var opts2=Input.Type==QuestionType.TrueFalse?["True","False"]:BuildOptions();var img=await _images.ApplyAsync(null,Input.Image,false,null);
        var audioUrl = Input.Audio is { Length: > 0 } ? await _audio.SaveAsync(Input.Audio, null) : Input.AudioUrl;_db.QuizQuestions.Add(new QuizQuestion{QuizId=quiz!.Id,QuestionText=Input.QuestionText.Trim(),Type=Input.Type,Points=Input.Points,OrderIndex=Input.OrderIndex>0?Input.OrderIndex:await _db.QuizQuestions.Where(x=>x.QuizId==quiz.Id).CountAsync()+1,OptionsJson=Input.Type is QuestionType.MultipleChoice or QuestionType.TrueFalse?JsonSerializer.Serialize(opts2):null,CorrectAnswerIndex=Input.Type is QuestionType.MultipleChoice or QuestionType.TrueFalse?Input.CorrectOptionNumber-1:null,CorrectAnswerText=Input.CorrectAnswerText?.Trim(),AudioUrl=audioUrl,ToneSequence=Input.ToneSequence?.Trim(),ImageUrl=img});await _db.SaveChangesAsync();TempData["StatusMessage"]="Question created.";return RedirectToPage("./Index");}private List<string> BuildOptions()=>new[]{Input.Option1,Input.Option2,Input.Option3,Input.Option4}.Where(x=>!string.IsNullOrWhiteSpace(x)).Select(x=>x!.Trim()).ToList();private async Task LoadQuizzesAsync()=>ViewData["QuizId"]=new SelectList(await _db.Quizzes.Include(q=>q.Lesson).ThenInclude(l=>l.Course).Where(q=>q.Lesson.Course.IsActive).OrderBy(q=>q.Lesson.Course.Title).ThenBy(q=>q.Lesson.OrderIndex).ThenBy(q=>q.Title).Select(q=>new{q.Id,Label=q.Lesson.Course.Title+" — "+q.Lesson.Title+" — "+q.Title}).ToListAsync(),"Id","Label",Input.QuizId);}
